import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 4
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)

    records = []
    for record in reader:
        if record and record[0].startswith("\ufeff"):
            record[0] = record[0].lstrip("\ufeff")
        if not record or all(not value.strip() for value in record):
            continue
        records.append([str(value) for value in record])

    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, record in enumerate(records) if len(record) == expected_width),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records) if len(record) > 1),
            0,
        )

    columns = records[header_index]
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
